DROP TABLE IF EXISTS `cms_category`;

CREATE TABLE `cms_category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父分类ID(0为根)',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_category_slug` (`slug`),
  KEY `idx_cms_category_parent_id` (`parent_id`),
  KEY `idx_cms_category_created_at` (`created_at`),
  KEY `idx_cms_category_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cms_page`;

CREATE TABLE `cms_page` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_page_slug` (`slug`),
  KEY `idx_cms_page_created_at` (`created_at`),
  KEY `idx_cms_page_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cms_tag`;

CREATE TABLE `cms_tag` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_tag_slug` (`slug`),
  KEY `idx_cms_tag_created_at` (`created_at`),
  KEY `idx_cms_tag_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contract_field`;

CREATE TABLE `contract_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_c_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_contract_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contract_field_blob`;

CREATE TABLE `contract_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_contract_field_blob_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_business_title`;

CREATE TABLE `crm_business_title` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业名称',
  `tax_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '税号',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户行',
  `bank_account` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账号',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_crm_business_title_name` (`name`),
  KEY `idx_crm_business_title_created_at` (`created_at`),
  KEY `idx_crm_business_title_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_contract`;

CREATE TABLE `crm_contract` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `contract_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同名称',
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '来源商机ID',
  `title_id` bigint unsigned DEFAULT NULL COMMENT '工商抬头ID',
  `total_amount` decimal(14,2) NOT NULL COMMENT '合同总额',
  `received_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已回款总额(累计维护)',
  `signed_date` date DEFAULT NULL COMMENT '签订日期',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '阶段(字典CONTRACT_STAGE)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人',
  `follow_time` datetime(3) DEFAULT NULL COMMENT '最新跟进时间',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '合同内容/备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `approval_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT '审批状态(NONE/PROCESSING/APPROVED/REJECTED/REVOKED)',
  PRIMARY KEY (`id`),
  KEY `idx_contract_customer` (`customer_id`),
  KEY `idx_crm_contract_opportunity_id` (`opportunity_id`),
  KEY `idx_crm_contract_stage` (`stage`),
  KEY `idx_contract_owner` (`owner_id`),
  KEY `idx_crm_contract_created_at` (`created_at`),
  KEY `idx_crm_contract_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `crm_contract` (`id`, `contract_no`, `name`, `customer_id`, `opportunity_id`, `title_id`, `total_amount`, `received_amount`, `signed_date`, `start_date`, `end_date`, `stage`, `owner_id`, `follower_id`, `follow_time`, `content`, `created_at`, `updated_at`, `deleted_at`, `approval_status`) VALUES
