  `method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回款方式(字典PAYMENT_METHOD)',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_crm_contract_payment_record_contract_id` (`contract_id`),
  KEY `idx_crm_contract_payment_record_plan_id` (`plan_id`),
  KEY `idx_crm_contract_payment_record_created_at` (`created_at`),
  KEY `idx_crm_contract_payment_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

