DROP TABLE IF EXISTS `crm_customer_collaboration`;

CREATE TABLE `crm_customer_collaboration` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `user_id` bigint unsigned NOT NULL COMMENT '协作人ID',
  `collaboration_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'READ_ONLY只读/COLLABORATION协作',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_customer_user` (`customer_id`,`user_id`),
  KEY `idx_crm_customer_collaboration_user_id` (`user_id`),
  KEY `idx_crm_customer_collaboration_created_at` (`created_at`),
  KEY `idx_crm_customer_collaboration_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_customer_contact`;

CREATE TABLE `crm_customer_contact` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `position` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职务',
  `department` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门',
  `is_key_decision_maker` tinyint DEFAULT '0' COMMENT '0否 1是关键决策人',
  `status` tinyint DEFAULT '1' COMMENT '1正常 2停用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_customer` (`customer_id`),
  KEY `idx_crm_customer_contact_created_at` (`created_at`),
  KEY `idx_crm_customer_contact_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_customer_owner_history`;

CREATE TABLE `crm_customer_owner_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '当时的负责人(进公海时NULL)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TAKE/RELEASE/TRANSFER/RECYCLE',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_owner_history_customer_id` (`customer_id`),
  KEY `idx_crm_customer_owner_history_owner_id` (`owner_id`),
  KEY `idx_crm_customer_owner_history_action` (`action`),
  KEY `idx_crm_customer_owner_history_created_at` (`created_at`),
  KEY `idx_crm_customer_owner_history_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

