  KEY `idx_crm_opportunity_created_at` (`created_at`),
  KEY `idx_crm_opportunity_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

