DROP TABLE IF EXISTS `crm_product`;

CREATE TABLE `crm_product` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `product_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编号',
  `category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(字典PRODUCT_CATEGORY)',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `standard_price` decimal(14,2) DEFAULT NULL COMMENT '标准价格',
  `cost_price` decimal(14,2) DEFAULT NULL COMMENT '成本价',
  `status` tinyint DEFAULT '1' COMMENT '1上架 2下架',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_crm_product_name` (`name`),
  KEY `idx_crm_product_category` (`category`),
  KEY `idx_crm_product_status` (`status`),
  KEY `idx_crm_product_created_at` (`created_at`),
  KEY `idx_crm_product_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_product_price`;

CREATE TABLE `crm_product_price` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL COMMENT '产品ID',
