DROP TABLE IF EXISTS `fin_invoice`;

CREATE TABLE `fin_invoice` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `invoice_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票号码',
  `invoice_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票类型(VAT_SPECIAL增值税专票/VAT_NORMAL普票/ELECTRONIC电子发票)',
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RECEIVED收票/ISSUED开票',
  `invoice_date` date NOT NULL COMMENT '开票日期',
  `amount` decimal(14,2) NOT NULL COMMENT '不含税金额',
  `tax_rate` decimal(5,4) DEFAULT NULL COMMENT '税率(如0.13)',
  `tax_amount` decimal(14,2) DEFAULT NULL COMMENT '税额',
  `total_amount` decimal(14,2) NOT NULL COMMENT '价税合计',
  `party_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对方名称(客户/供应商)',
  `party_tax_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对方税号',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONTRACT/PURCHASE/SALES',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_invoice_invoice_no` (`invoice_no`),
  KEY `idx_fin_invoice_direction` (`direction`),
  KEY `idx_fin_invoice_invoice_date` (`invoice_date`),
  KEY `idx_fin_invoice_created_at` (`created_at`),
  KEY `idx_fin_invoice_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_voucher`;

CREATE TABLE `fin_voucher` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `voucher_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '凭证编号',
  `voucher_date` date NOT NULL COMMENT '凭证日期',
  `account_id` bigint unsigned NOT NULL COMMENT '科目ID',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '摘要',
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DEBIT借/CREDIT贷',
  `amount` decimal(14,2) NOT NULL COMMENT '金额',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型(CONTRACT_PAYMENT/PURCHASE/SALES等)',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/CONFIRMED',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '制单人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_voucher_voucher_no` (`voucher_no`),
  KEY `idx_fin_voucher_voucher_date` (`voucher_date`),
  KEY `idx_fin_voucher_account_id` (`account_id`),
  KEY `idx_fin_voucher_status` (`status`),
  KEY `idx_fin_voucher_created_at` (`created_at`),
  KEY `idx_fin_voucher_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `follow_up_plan`;

CREATE TABLE `follow_up_plan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划类型',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划内容',
  `plan_time` datetime(3) NOT NULL COMMENT '计划跟进时间',
  `remind_time` datetime(3) DEFAULT NULL COMMENT '提醒时间(早于plan_time)',
  `owner_id` bigint unsigned NOT NULL COMMENT '负责人',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '关联商机',
  `contact_id` bigint unsigned DEFAULT NULL COMMENT '关联联系人',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同',
  `status` tinyint DEFAULT '0' COMMENT '0待办 1已转记录 2已跳过',
  `reminded` tinyint DEFAULT '0' COMMENT '是否已发提醒',
  `record_id` bigint unsigned DEFAULT NULL COMMENT '转入的记录ID',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_plan_owner_id` (`owner_id`),
  KEY `idx_follow_up_plan_customer_id` (`customer_id`),
  KEY `idx_follow_up_plan_opportunity_id` (`opportunity_id`),
  KEY `idx_follow_up_plan_contact_id` (`contact_id`),
  KEY `idx_follow_up_plan_contract_id` (`contract_id`),
  KEY `idx_follow_up_plan_created_at` (`created_at`),
  KEY `idx_follow_up_plan_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `follow_up_record`;

CREATE TABLE `follow_up_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进类型(WECHAT/PHONE/VISIT/EMAIL/OTHER)',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进内容',
  `follow_time` datetime(3) NOT NULL COMMENT '跟进发生时间',
  `owner_id` bigint unsigned NOT NULL COMMENT '负责人',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '关联商机',
  `contact_id` bigint unsigned DEFAULT NULL COMMENT '关联联系人',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '来源计划(计划转记录时填)',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_record_owner_id` (`owner_id`),
  KEY `idx_follow_up_record_customer_id` (`customer_id`),
  KEY `idx_follow_up_record_opportunity_id` (`opportunity_id`),
  KEY `idx_follow_up_record_contact_id` (`contact_id`),
  KEY `idx_follow_up_record_contract_id` (`contract_id`),
  KEY `idx_follow_up_record_plan_id` (`plan_id`),
  KEY `idx_follow_up_record_created_at` (`created_at`),
  KEY `idx_follow_up_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `follow_up_record_field`;

CREATE TABLE `follow_up_record_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进记录ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_f_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_follow_up_record_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `follow_up_record_field_blob`;

CREATE TABLE `follow_up_record_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_record_field_blob_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `hrm_attendance_clock`;

CREATE TABLE `hrm_attendance_clock` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `clock_date` date NOT NULL COMMENT '打卡日期',
  `clock_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CHECK_IN/CHECK_OUT',
  `clock_time` datetime NOT NULL COMMENT '打卡时间',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡地点',
  `longitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经度',
  `latitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纬度',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_clock_emp_date` (`employee_id`,`clock_date`),
  KEY `idx_hrm_attendance_clock_created_at` (`created_at`),
  KEY `idx_hrm_attendance_clock_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `hrm_attendance_summary`;

CREATE TABLE `hrm_attendance_summary` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `year_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '年月(2026-08)',
  `work_days` bigint DEFAULT '22' COMMENT '应出勤天数',
  `actual_days` bigint DEFAULT '0' COMMENT '实际出勤天数',
  `late_count` bigint DEFAULT '0' COMMENT '迟到次数',
  `early_count` bigint DEFAULT '0' COMMENT '早退次数',
  `absent_days` decimal(5,1) DEFAULT '0.0' COMMENT '缺勤天数',
  `leave_days` decimal(5,1) DEFAULT '0.0' COMMENT '请假天数',
  `overtime_hours` decimal(5,1) DEFAULT '0.0' COMMENT '加班时长',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_att_summary` (`employee_id`,`year_month`),
  KEY `idx_hrm_attendance_summary_created_at` (`created_at`),
  KEY `idx_hrm_attendance_summary_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `hrm_department`;

CREATE TABLE `hrm_department` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父部门ID(0为根)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部门名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门编码',
  `leader` bigint unsigned DEFAULT NULL COMMENT '负责人ID(关联sys_user)',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1正常 0禁用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hrm_department_code` (`code`),
  KEY `idx_hrm_department_parent_id` (`parent_id`),
  KEY `idx_hrm_department_created_at` (`created_at`),
  KEY `idx_hrm_department_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

