  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_hrm_position_change_employee_id` (`employee_id`),
  KEY `idx_hrm_position_change_created_at` (`created_at`),
  KEY `idx_hrm_position_change_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

