DROP TABLE IF EXISTS `sys_api_key`;

CREATE TABLE `sys_api_key` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT '关联用户ID',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Key名称(如''我的CLI'')',
  `key_prefix` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前缀(qzt_)',
  `key_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA256 hash',
  `last_used_at` datetime DEFAULT NULL COMMENT '最后使用时间',
  `last_used_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后使用IP',
  `expires_at` datetime DEFAULT NULL COMMENT '过期时间(空=永不过期)',
  `status` tinyint DEFAULT '1' COMMENT '1启用0禁用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_api_key_key_hash` (`key_hash`),
  KEY `idx_sys_api_key_user_id` (`user_id`),
  KEY `idx_sys_api_key_status` (`status`),
  KEY `idx_sys_api_key_created_at` (`created_at`),
  KEY `idx_sys_api_key_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_api_key` (`id`, `user_id`, `name`, `key_prefix`, `key_hash`, `last_used_at`, `last_used_ip`, `expires_at`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, '测试CLI Key', 'qzt_', '1ee600f17b52fc5aa68433545a34865696198e93d74ed3cd29b705b34f23ccbb', '2026-08-04 10:19:57', '::1', NULL, 1, '2026-08-04 10:19:56.133', '2026-08-04 10:19:56.978', NULL),
(2, 1, 'MCP测试', 'qzt_', 'eeab49a634ffcd4ce191c326585ef117a8c20a4b6d762ca9151062edf2d37370', NULL, '', NULL, 1, '2026-08-04 10:20:16.690', '2026-08-04 10:20:16.690', NULL);

DROP TABLE IF EXISTS `sys_config`;

CREATE TABLE `sys_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分组',
  `key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '值(统一字符串存储)',
  `type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'string' COMMENT 'string/int/bool/float/json/text/select',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT 'select 选项或校验规则(JSON)',
  `is_public` tinyint(1) DEFAULT '0' COMMENT '是否免鉴权可读',
  `editable` tinyint(1) DEFAULT '1' COMMENT '是否允许后台编辑',
  `builtin` tinyint(1) DEFAULT '0' COMMENT '内置(不可删除)',
  `sort` bigint DEFAULT '0',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_config_key` (`key`),
  KEY `idx_sys_config_group` (`group`),
  KEY `idx_sys_config_created_at` (`created_at`),
  KEY `idx_sys_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sys_dict`;

CREATE TABLE `sys_dict` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典编码',
  `status` tinyint DEFAULT '1' COMMENT '1-启用 0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `sort` bigint DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_dict_code` (`code`),
  KEY `idx_sys_dict_created_at` (`created_at`),
  KEY `idx_sys_dict_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

