DROP TABLE IF EXISTS `sys_message`;

CREATE TABLE `sys_message` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sender_id` bigint unsigned DEFAULT NULL COMMENT '发送人ID(系统消息=0)',
  `receiver_id` bigint unsigned DEFAULT NULL COMMENT '接收人ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `is_read` tinyint DEFAULT '0' COMMENT '是否已读(0未读 1已读)',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_sender_id` (`sender_id`),
  KEY `idx_sys_message_receiver_id` (`receiver_id`),
  KEY `idx_sys_message_is_read` (`is_read`),
  KEY `idx_sys_message_created_at` (`created_at`),
  KEY `idx_sys_message_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sys_module_field`;

CREATE TABLE `sys_module_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `form_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属表单ID',
  `internal_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段内置Key',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段名称',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段类型',
  `mobile` tinyint DEFAULT '0' COMMENT '是否移动端',
  `pos` bigint DEFAULT '0' COMMENT '排序',
  `readable` tinyint DEFAULT '1' COMMENT '是否可见',
  `editable` tinyint DEFAULT '1' COMMENT '是否可编辑',
  PRIMARY KEY (`id`),
  KEY `idx_form` (`form_id`),
  KEY `idx_form_internal` (`internal_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_module_field` (`id`, `form_id`, `internal_key`, `name`, `type`, `mobile`, `pos`, `readable`, `editable`) VALUES
('cf_address', 'f_customer', 'address', '详细地址', 'TEXTAREA', 1, 30, 1, 1),
('cf_email', 'f_customer', 'email', '邮箱', 'INPUT', 1, 20, 1, 1),
('cf_phone', 'f_customer', 'phone', '电话', 'PHONE', 1, 10, 1, 1),
('cf_website', 'f_customer', 'website', '网址', 'INPUT', 1, 40, 1, 1);

DROP TABLE IF EXISTS `sys_module_field_blob`;

CREATE TABLE `sys_module_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prop` text COLLATE utf8mb4_unicode_ci COMMENT '字段属性JSON',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_module_field_blob` (`id`, `prop`) VALUES
('cf_address', '');

DROP TABLE IF EXISTS `sys_module_form`;

CREATE TABLE `sys_module_form` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `form_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块标识',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单名称',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_module_form_form_key` (`form_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

