DROP TABLE IF EXISTS `sys_role`;

CREATE TABLE `sys_role` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort` bigint DEFAULT '0',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_role_code` (`code`),
  KEY `idx_sys_role_created_at` (`created_at`),
  KEY `idx_sys_role_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_role` (`id`, `name`, `code`, `sort`, `status`, `remark`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '超级管理员', 'super_admin', 0, 1, '超级管理员，拥有所有权限', '2026-08-03 11:08:19.080', '2026-08-04 09:59:56.304', NULL);

DROP TABLE IF EXISTS `sys_site_config`;

CREATE TABLE `sys_site_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `site_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点名称(企业名)',
  `logo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Logo图片URL',
  `favicon_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Favicon图标URL',
  `slogan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌标语/Slogan',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点描述(SEO meta description)',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `contact_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司地址',
  `contact_qq` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客服QQ',
  `contact_wechat` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信号/客服二维码URL',
  `work_hours` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作时间(如 周一至周五 9:00-18:00)',
  `weibo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微博链接',
  `wechat_qr_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信公众号二维码URL',
  `linked_in_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LinkedIn链接',
  `icp_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ICP备案号(如 京ICP备xxxxxxxx号)',
  `public_security_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案号',
  `public_security_beian_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案跳转链接',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SEO关键词(逗号分隔)',
  `analytics_code` text COLLATE utf8mb4_unicode_ci COMMENT '统计代码(GA/百度统计等JS)',
  `copyright` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版权声明(如 © 2024 某某科技有限公司)',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sys_site_config_created_at` (`created_at`),
  KEY `idx_sys_site_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_site_config` (`id`, `site_name`, `logo_url`, `favicon_url`, `slogan`, `description`, `contact_phone`, `contact_email`, `contact_address`, `contact_qq`, `contact_wechat`, `work_hours`, `weibo_url`, `wechat_qr_url`, `linked_in_url`, `icp_beian`, `public_security_beian`, `public_security_beian_url`, `keywords`, `analytics_code`, `copyright`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'qzt-dev', '', '', '', '企业级业务管理平台', '', '', '', '', '', '周一至周五 9:00-18:00', '', '', '', '', '', '', '', '', '© 2024 你的企业名称', '2026-08-04 10:51:25.610', '2026-08-04 10:51:25.610', NULL);

DROP TABLE IF EXISTS `sys_storage_config`;

CREATE TABLE `sys_storage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `driver` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'local' COMMENT '存储驱动(local/oss)',
  `local_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT './storage/uploads' COMMENT '本地存储根目录',
  `resource_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地资源访问域名',
  `oss_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Endpoint',
  `oss_access_key_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeyID',
  `oss_access_key_secret` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeySecret(脱敏不返回)',
  `oss_bucket_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Bucket名称',
  `oss_custom_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS 自定义域名/CDN',
  `max_upload_mb` bigint DEFAULT '20' COMMENT '单文件大小上限(MB)',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sys_storage_config_created_at` (`created_at`),
  KEY `idx_sys_storage_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_storage_config` (`id`, `driver`, `local_path`, `resource_domain`, `oss_endpoint`, `oss_access_key_id`, `oss_access_key_secret`, `oss_bucket_name`, `oss_custom_domain`, `max_upload_mb`, `remark`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'local', './storage/uploads', 'http://localhost:9000', '', '', '', '', '', 10, '后台修改测试', '2026-08-04 03:40:27.089', '2026-08-04 03:40:45.534', NULL);

DROP TABLE IF EXISTS `sys_user`;

CREATE TABLE `sys_user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nickname` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `token_version` bigint DEFAULT '0' COMMENT '会话版本，自增使旧 token 失效',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `wecom_user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企业微信UserID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_user_username` (`username`),
  KEY `idx_sys_user_created_at` (`created_at`),
  KEY `idx_sys_user_deleted_at` (`deleted_at`),
  KEY `idx_sys_user_wecom_user_id` (`wecom_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sys_user` (`id`, `username`, `password`, `nickname`, `avatar`, `email`, `phone`, `status`, `token_version`, `created_at`, `updated_at`, `deleted_at`, `wecom_user_id`) VALUES
(1, 'admin', '$2a$10$PDWTu7duPS5prowUAP5cwOQPIijZbuTcj.e2Z71t/sm3ZUSRrmYT2', '管理员', '', 'admin@test.com', '', 1, 1, '2026-08-03 11:08:19.224', '2026-08-04 10:20:07.354', NULL, '');

DROP TABLE IF EXISTS `cms_article`;

CREATE TABLE `cms_article` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '摘要',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `category_id` bigint unsigned DEFAULT NULL COMMENT '分类ID',
  `author_id` bigint unsigned DEFAULT NULL COMMENT '作者用户ID',
  `author_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作者昵称(快照)',
  `status` tinyint DEFAULT '0' COMMENT '0草稿 1已发布',
  `is_top` tinyint DEFAULT '0' COMMENT '0否 1置顶',
  `is_hot` tinyint DEFAULT '0' COMMENT '0否 1热门',
  `view_count` bigint DEFAULT '0' COMMENT '浏览量',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cms_article_slug` (`slug`),
  KEY `idx_cms_article_category_id` (`category_id`),
  KEY `idx_cms_article_author_id` (`author_id`),
  KEY `idx_cms_article_status` (`status`),
  KEY `idx_cms_article_created_at` (`created_at`),
  KEY `idx_cms_article_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_cms_article_category` FOREIGN KEY (`category_id`) REFERENCES `cms_category` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sys_dict_item`;

CREATE TABLE `sys_dict_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `dict_id` bigint unsigned NOT NULL COMMENT '所属字典ID',
  `label` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示文本',
  `value` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储值',
  `sort` bigint DEFAULT '0',
  `status` tinyint DEFAULT '1' COMMENT '1-启用 0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_item_dict_id` (`dict_id`),
  KEY `idx_sys_dict_item_created_at` (`created_at`),
  KEY `idx_sys_dict_item_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_sys_dict_items` FOREIGN KEY (`dict_id`) REFERENCES `sys_dict` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

